// Extract key data from execution record
const data = $input.first().json;
const nodes = data.data?.resultData?.runData || {};

const failedNodes = [];
const slowNodes = [];

for (const [nodeName, runs] of Object.entries(nodes)) {
  if (runs && runs.length > 0) {
    const run = runs[runs.length - 1];
    if (run.error) {
      failedNodes.push({ node: nodeName, error: run.error.message });
    }
    if (run.executionTime && run.executionTime > 5000) {
      slowNodes.push({ node: nodeName, timeMs: run.executionTime });
    }
  }
}

return [{ json: { failedNodes, slowNodes, totalNodes: Object.keys(nodes).length } }];

